function frame(now){const dt=Math.min((now-last)/1000||0,.035);last=now;if(mode==='arrival'){music(dt);arrivalStep(dt);}else if(mode==='escape'){shipEscapeStep(dt);}else if(mode==='visit'){homeStep(dt);}else update(dt);render();requestAnimationFrame(frame);}
async function load(){const entries=[['characters','assets/characters.webp'],['environments','assets/environments.webp'],['extras','assets/extras.webp'],['novaMotion','assets/nova-motion.webp'],['sylMotion','assets/syl-motion.webp'],['brawl','assets/brawl-motion.webp'],['novaReady','assets/nova-ready.webp'],['sylJump','assets/syl-jump.webp'],['facilityPano','assets/facility-panorama.webp'],['forestPano','assets/forest-panorama.webp'],['novaUnarmed','assets/nova-unarmed.webp'],['sylUnarmed','assets/syl-unarmed.webp'],['fantasy','assets/fantasy.webp'],['tour','assets/ship-tour.webp'],['residents','assets/residents.webp'],['beachGuests','assets/beach-guests.webp'],['home','assets/home.webp'],['homeContinuous','assets/home-continuous.webp'],['terrain','assets/terrain.webp'],['ship','assets/ship.webp'],['summonMotion','assets/summon-motion.webp']];let done=0;await Promise.all(entries.map(async([key,url])=>{assets[key]=await new Promise(resolve=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>resolve(null);im.src=url;});$('#loading').textContent='Loading island art · '+(++done)+'/'+entries.length;}));if(!assets.characters||!assets.environments){$('#loading').innerHTML='Art failed to load. <button onclick="location.reload()">Reload game</button>';return;}$('#loading').hidden=true;title();requestAnimationFrame(frame);}
